  admin_indexer_refresh: "刷新",
  admin_indexer_header_tools_filter_hint:
    "提交「刷新」会重新请求 GET …/indexer/health；对账报告列表、可观测与返回工作台等链接为站内导航（不触发健康重拉）。",
  admin_indexer_ops_heading: "内部索引与对账（运维）",
  admin_indexer_ops_hint:
    "本页不调用写入类 internal 接口。请在可信主机（调度任务或对 localhost/内网 API 执行 curl）：\n• POST /api/v1/internal/indexer-tick — 拉取日志并更新投影/checkpoint\n• POST /api/v1/internal/indexer-replay — 按 event_log 重放 orders_projection\n• POST /api/v1/internal/indexer-reconcile — 比对 orders 与 orders_projection；body 可含 persist、chain_id、rpc_escrow_samples（1～10）；200 根级含 issues_total、projection_reconcile_clean（与 stats 同源，便于 jq）\n• GET /api/v1/internal/indexer-status — checkpoint / 滞后快照；可选 ?live_reconcile=1 即时只读 orders↔projection 对账块\n• bash scripts/indexer-reconcile-probe.sh 或 internal-indexer-ops.sh probe — 退出码 0 当且仅当即时 projection_reconcile_clean（须 jq + 密钥）\n• bash scripts/internal-indexer-ops.sh status|status --live-reconcile|probe|recover|evidence|evidence-bundle|tick|replay|reconcile — recover 转 indexer-reorg-recovery.sh；evidence-bundle 生成 manifest 与可选 zip（RUNBOOK §2.55）\n若配置了 INTERNAL_API_SECRET，须加请求头 X-Internal-Api-Secret。\nAdmin 侧保持只读：健康快照与对账报告列表/详情。curl 示例见仓库 ops/RUNBOOK.md §2.55；契约见 docs/spec/04-后端与API.md §3.4（内部 API）。全量链上与证据归档见 docs/spec/110-阶段开发链上索引器与事件同步器.md。",
  admin_indexer_ops_projection_sync_note:
    "在开启 INDEXER_REORG_SYNC_ORDERS_FROM_PROJECTION_AFTER_REWIND=1 时，POST /api/v1/internal/indexer-reorg-rewind（或与 tick 单次自动回滚同源路径）的响应体可含 orders_table_projection_sync：含 clear_terminal_orphan_escrow_enabled（与 INDEXER_REORG_SYNC_CLEAR_ORPHAN_ESCROW_TERMINAL 一致，便于留痕）；cleared_orphan_escrow_pre_funded 统计在无投影行时对 draft/created/accepted 清除孤立 escrow 列；另设 INDEXER_REORG_SYNC_CLEAR_ORPHAN_ESCROW_TERMINAL=1 时 cleared_orphan_escrow_terminal_no_projection 对 completed/disputed/refunded/partially_refunded/slashed/cancelled 亦清 escrow 列、保持 status；否则终态计入 skipped_no_projection_non_escrowed_with_escrow（须人工复核）。全表按链回滚 orders 仍为 Target（orders 无 chain_id，见 110 §3.1.4）。详见 docs/spec/110 §3.1.3。",

