  traveltrust_sticky_more: "更多入口",
  traveltrust_sticky_dismiss: "关闭",
  traveltrust_settlementTitle: "结算与代币（Trust / 常驻披露）",
  traveltrust_quickExplainTitle: "如何运作 — 三步",
  traveltrust_step_book_title: "预订",
  traveltrust_step_book_body: "创建或选择行程方案，与向导对齐条款，并生成带明确条件的旅游订单。",
  traveltrust_step_match_title: "撮合确认",
  traveltrust_step_match_body: "向导满足链上资格与档期规则；双方在入金托管前对最终方案达成双边确认。",
  traveltrust_step_travel_title: "出行与结算",
  traveltrust_step_travel_body:
    "按方案出行；行程完成先在链下确认。释放托管遵循合约路径（若适用），与单次「点完成即放款」不是同一动作。",
  traveltrust_quickExplain_footnote:
    "产品主链口径：链下确认完成 →（若适用）评分 → 链上 release；详见 01 / 53。",
  traveltrust_problem_title: "为何需要更好的旅游金融轨道",
  traveltrust_problem_body: "跨境支付摩擦、平台经济不透明，以及行程变更或争议时救济路径不清。",
  traveltrust_solution_title: "TravelTrust 提供什么",
  traveltrust_solution_body:
    "以订单为中心的托管（Escrow）、按部署落地的向导质押与资格（Registry），以及与 82–84 文档分层的治理经济叙事——不将路线图代币与行程结算币混读。",
  traveltrust_highlights_title: "核心能力",
  traveltrust_matrix_title: "叙事与痛点对照",
  traveltrust_matrix_lead:
    "左栏为市场语境，右栏为协议与产品回应；仅供理解架构，不构成投资建议。",
  traveltrust_highlight_escrow_title: "托管与结算",
  traveltrust_highlight_escrow_body:
    "行程资金进链上 Escrow，释放顺序遵循 01/53；结算以 allowlist 稳定币为主，不将路线图代币表述为已替代行程结算币。",
  traveltrust_highlight_match_title: "撮合与身份",
  traveltrust_highlight_match_body:
    "向导资格与档期约束走 Registry；撮合主入口为自由市场，链下确认与链上资金路径分治。",
  traveltrust_highlight_gov_title: "治理与经济分层",
  traveltrust_highlight_gov_body:
    "TTG、Country Pool、FeeRouter 以 82–84 为 SSOT；承销档位与可分配费用基数两套数字勿混读（84 §1.3）。",
  traveltrust_highlight_trust_title: "争议与信任",
  traveltrust_highlight_trust_body:
    "争议与仲裁路径见产品规格；页内动效与统计为演示，不等同链上实时成交或 TVL。",
  traveltrust_quick_section_eyebrow: "产品路径",
  traveltrust_nav_aria: "本页章节导航",
  traveltrust_nav_intro_sr: "跳转到网络落地页各主要模块。",
