  traveltrust_nav_faq: "FAQ",
  traveltrust_nav_cta: "入口",
  traveltrust_trust_title: "信任与事实层",
  traveltrust_trust_body:
    "当前产品切片中，订单以 EVM L2 上 allowlist 稳定币结算。标注为 Target 的能力（如 TTG、Country Pool、FeeRouter 扩展）属路线图，除非你的环境已另行部署。",
  traveltrust_trust_bullet_escrow:
    "订单资金走链上 Escrow；释放顺序遵循 01 / 53：行程完成确认、（若适用）评分与双方确认后，再链上 release。",
  traveltrust_trust_bullet_allowlist:
    "行程结算以 allowlist 稳定币为主；代币白名单与合约配置以部署环境与 GET /meta 为准。",
  traveltrust_trust_bullet_guide:
    "向导接单与档期占用与业务规则一致；质押与 Registry 以已部署合约为准，叙事与 81 / 08-3 分层。",
  traveltrust_trust_bullet_disputes:
    "争议路径与 01 / 03 对齐：结构化流程下人工裁决与（若配置）合约执行；入口见争议与帮助中心。",
  traveltrust_trust_bullet_target:
    "页面动画与演示数字为视觉隐喻或示例，不等同链上实时成交；DAO、区域池、费路由扩展须标注 Target 或未部署前不构成承诺（13-1 表 2-续、83 附录 I.0 口径）。",
  traveltrust_cta_title: "体验真实产品路径",
  traveltrust_cta_body: "本页不提供模拟认购；请走与游客/向导相同的功能入口。",
  traveltrust_cta_market: "打开自由市场",
  traveltrust_cta_home: "主站体验",
  /** 锚点 `#fee-router` — 07 §5.3A + §5.2A */
  traveltrust_link_feeRouter: "费路由自检",
  /** 锚点 `#token-system` — 85 §十四 */
  traveltrust_link_tokenSystem: "代币分层说明",
  traveltrust_faq_title: "常见问题",
  traveltrust_faq_intro:
    "以下为产品向说明；对外法务口径与辖区披露以 08-4 及定稿清单为准。",
  traveltrust_faq_q1: "旅游托管资金是否安全？",
  traveltrust_faq_a1:
    "在已配置部署的环境中，订单走链上 Escrow，并以 allowlist 稳定币结算；钱包由你自持，应用仅编排签名。非托管边界详见 08-4 与帮助中心。",
  traveltrust_faq_q2: "是否必须持有某种代币才能下单？",
  traveltrust_faq_a2:
    "现行产品路径以 EVM L2 上 allowlist 稳定币（如 USDC）结算。TTG、Country Pool、FeeRouter 扩展等在 82–84 中按 Target / 路线图表述，不得理解为已替代行程结算币。",
  traveltrust_faq_q3: "结算与释放如何发生？",
  traveltrust_faq_a3:
    "主链口径见 01 / 53：双边确认、托管入金、链下确认行程完成、（若适用）评分，条件满足后再链上 release；并非单一「完成」即等同放款。",
  traveltrust_faq_q4: "某条链或功能是否已上线？",
  traveltrust_faq_a4:
    "取决于你所连接的环境与部署。请以运行配置及 GET /meta 为准；本页为叙事入口，不承担实时链上状态看板职责。",
  traveltrust_faq_q5: "争议如何处理？",
  traveltrust_faq_a5:
    "与 01 / 03 一致：结构化路径下，在已配置时由人工裁决后走合约执行。产品入口见 /disputes 与 /help。",
  traveltrust_faq_visual_note:
    "若后续增加动效演示，仅为视觉隐喻，不代表链上实时成交或路由真值。",
  traveltrust_settlementBody:
    "旅行订单链上托管（Escrow）在 MVP 与现行实现中以 allowlist 稳定币（如 USDC）为主要结算手段。治理代币（TTG）或 Country Pool 等叙事若为路线图或融资层内容，须标注为 Target，不得暗示已替代订单结算币。",
  traveltrust_feeRouter_section_title: "平台费路由（运维/集成）",
  traveltrust_feeRouter_section_lead:
    "链上创建 Escrow 时，平台费收单地址须与 GET /meta 及构建环境变量一致（Runbook §7.1）。以下状态仅反映当前浏览器会话，不代表协议资金规模承诺。",
