  help_title: "帮助中心",
  help_desc:
    "本页摘要与《服务条款》《隐私政策》及对外口径包（08-4）一致，便于自助查询；完整法务文本以定稿版为准。",
  help_platform: "平台与资金",
  help_disputes: "申诉与争议",
  help_terms: "服务条款",
  help_privacy: "隐私政策",
  help_termsIntro: "完整规则与法务口径见 ",
  help_docNote: "；文档版本与定稿日期见项目 08-4 文末。",
  help_backHome: "返回首页",
  help_platformBullet1: "TravelTrust 为去中心化旅行预订协议，资金在链上 Escrow，平台不托管用户资金。",
  help_platformBullet2: "多签具备 Pause/冻结能力属于运维与安全应急权限；Pause 时仅暂停链上转出，不转移资产所有权。",
  help_platformBullet3:
    "当前阶段为混合治理态（多签、人工仲裁、Pause、Runbook 等）；与「纯无许可、完全链上自治」叙事不同，详见《服务条款》与 08-4。",
  help_disputesParagraph:
    "订单争议、证据提交与仲裁流程以《服务条款》与对外口径包（08-4）为准。链上 Pause（暂停）期间：通常仅可查看订单与余额、提交申诉材料；不可新建订单或执行链上转出。恢复条件与例外见 08-4 第 6 章与服务条款。",
  help_faqTitle: "常见问题",
  help_faqPayQ: "如何支付与查看托管？",
  help_faqPayA:
    "在「订单」完成接单与链上流程后，可通过支付说明页查看步骤摘要，并凭订单 ID 打开对应托管详情（链上 deposit、完成、争议等须按页面指引与钱包签名）。",
  help_faqPayCta: "支付与托管说明",
  help_faqPayDeepLink:
    "直达链接：/pay?orderId=<订单UUID> 会预填订单号并显示「打开托管详情」按钮（请将 <订单UUID> 换成你的订单 ID）。",
  help_faqStakingQ: "向导质押与资格从哪进入？",
  help_faqStakingA: "质押与 Registry 资格涉及链上合约交互；页面内会说明风险与操作入口，请使用兼容网络的钱包。",
  help_faqStakingCta: "质押与申请入口",
  help_faqEscrowQ: "找不到托管详情页？",
  help_faqEscrowA: "托管详情路径为 /escrow/{订单UUID}。请先在「我的订单」复制订单 ID，或在支付页输入后跳转。",
  help_faqEscrowCta: "我的订单",
  /** 07 §5.2A / Runbook §7.1：集成与部署 */
  help_faqFeeRouterQ: "创建托管时报平台费 / FeeRouter 地址相关错误？",
  help_faqFeeRouterA:
    "链上托管使用的平台费收单地址须与 GET /meta（chain.contracts）及构建侧 NEXT_PUBLIC_FEE_ROUTER_ADDRESS、后端 FEE_ROUTER_ADDRESS 一致；不一致会导致 createEscrow 失败。详见 Runbook §7.1 与治理侧费路由页。",
  help_faqDisputeQ: "发生争议怎么办？",
  help_faqDisputeA: "可在争议列表查看状态与证据相关说明；裁决与资金执行规则以服务条款与对外口径包（08-4）为准。",
